import numpy as np
from scipy import stats
from data import D, SEGS, CHECKS

def pooled_resid(c):
    res=[]
    for s in SEGS:
        a=np.array(D[(c,s)]); res.append(a-np.median(a))
    return np.concatenate(res)

for c in CHECKS:
    r=pooled_resid(c)
    r=r[np.abs(r)<2000]
    print('='*70); print(c,'n=',len(r))
    # candidate fits
    for df in [2,2.5,3,4,5,6,8,10,15]:
        # MLE scale for t
        def nll(scale):
            return -np.sum(stats.t.logpdf(r/ scale, df))
        from scipy.optimize import minimize_scalar
        res=minimize_scalar(nll,bounds=(1,500),method='bounded')
        s=res.x
        ll=-res.fun
        ks=stats.kstest(r/s,'t',args=(df,))
        print(f'  t df={df:4} scale={s:7.1f} nll={ll:9.1f} ks={ks.statistic:.3f} p={ks.pvalue:.3f}')
    # candidate: laplace
    from scipy.optimize import minimize_scalar
    def nll_l(scale):
        return np.sum(np.log(2*scale)+np.abs(r)/scale)
    res=minimize_scalar(nll_l,bounds=(1,500),method='bounded')
    ks=stats.kstest(r/res.x,'laplace')
    print(f'  laplace scale={res.x:7.1f} nll={res.fun:9.1f} ks={ks.statistic:.3f} p={ks.pvalue:.3f}')
    # candidate: normal
    def nll_n(scale):
        return np.sum(0.5*np.log(2*np.pi*scale**2)+0.5*(r/scale)**2)
    res=minimize_scalar(nll_n,bounds=(1,500),method='bounded')
    ks=stats.kstest(r/res.x,'norm')
    print(f'  normal scale={res.x:7.1f} nll={res.fun:9.1f} ks={ks.statistic:.3f} p={ks.pvalue:.3f}')
    # mixture: 0.8 N(0,s1)+0.2 N(0,s2) grid search
    best=None
    for p in [0.05,0.1,0.15,0.2,0.25,0.3]:
        for s1 in [10,20,30,40,50,60,80]:
            for s2 in [100,150,200,300,500,1000,3000]:
                lp=np.log(p*stats.norm.pdf(r,0,s1)+(1-p)*stats.norm.pdf(r,0,s2))
                nll=-np.sum(lp)
                if best is None or nll<best[0]: best=(nll,p,s1,s2)
    print(f'  2mix best nll={best[0]:.1f} p={best[1]} s1={best[2]} s2={best[3]}')
    # central fraction
    print('  |r|<30:',np.mean(np.abs(r)<30),' <60:',np.mean(np.abs(r)<60),' <100:',np.mean(np.abs(r)<100),' <200:',np.mean(np.abs(r)<200))

import numpy as np
from scipy import stats
from data import D, SEGS, CHECKS

def em_laplace_mixture(X, K=2, restarts=20, seed=0):
    rng=np.random.default_rng(seed); X=np.asarray(X,float)
    best=None
    for _ in range(restarts):
        if K==2:
            # init: random split by magnitude
            q=np.abs(X)>np.median(np.abs(X))
            w=q.mean(); b1=max(np.abs(X[q]).mean() if q.any() else 20,1); b2=max(np.abs(X[~q]).mean() if (~q).any() else 200,10)
            th=np.array([w,b1,b2])
        else:
            th=np.array([0.7,0.2,0.1,20,60,300])
        for it in range(500):
            w=th[0]; b1=th[1]; b2=th[2]
            p1=w*stats.laplace.pdf(X,0,b1); p2=(1-w)*stats.laplace.pdf(X,0,b2)
            tot=p1+p2; r1=p1/tot
            w=r1.mean(); b1=(r1*np.abs(X)).sum()/max(r1.sum(),1e-9); b2=((1-r1)*np.abs(X)).sum()/max((1-r1).sum(),1e-9)
            th=np.array([w,b1,b2])
        ll=np.sum(np.log(w*stats.laplace.pdf(X,0,b1)+(1-w)*stats.laplace.pdf(X,0,b2)))
        if best is None or ll>best[0]: best=(ll,*th)
    return best

def laplace_cdf(x,b):
    return 0.5+0.5*np.sign(x)*(1-np.exp(-np.abs(x)/b))

class Noise:
    def __init__(self,w,b1,b2):
        self.w,self.b1,self.b2=w,b1,b2
    def cdf(self,x):
        x=np.asarray(x,float)
        return self.w*laplace_cdf(x,self.b1)+(1-self.w)*laplace_cdf(x,self.b2)

def build_model():
    locs={}; noises={}
    for c in CHECKS:
        locs[c]={s:float(np.median(D[(c,s)])) for s in SEGS}
        r=np.concatenate([np.array(D[(c,s)])-locs[c][s] for s in SEGS])
        ll,w,b1,b2=em_laplace_mixture(r,2,restarts=30)
        # KS
        u=np.sort(r); F=(w*laplace_cdf(u,b1)+(1-w)*laplace_cdf(u,b2))
        n=len(u); emp=np.arange(1,n+1)/n
        ks=max(np.max(np.abs(F-emp)),np.max(np.abs((1-emp)-F)))
        noises[c]=Noise(w,b1,b2)
        print(f'{c}: locs={[round(locs[c][s],1) for s in SEGS]}')
        print(f'   2lap w={w:.3f} b1={b1:.2f} b2={b2:.2f} ll={ll:.1f} KS={ks:.3f}')
        # single-laplace for comparison
        b1s=np.mean(np.abs(r))
        F1=laplace_cdf(u,b1s); ks1=max(np.max(np.abs(F1-emp)),np.max(np.abs((1-emp)-F1)))
        print(f'   1lap b={b1s:.2f} KS={ks1:.3f}')
    return locs,noises

if __name__=='__main__':
    locs,noises=build_model()
    # empirical band counts per cell vs model
    edges=[560,630,690,750,820]
