            a=np.array(D[(c,s)])
            emp=np.array([np.mean(a<edges[0]),np.mean((a>=edges[0])&(a<edges[1])),np.mean((a>=edges[1])&(a<edges[2])),
                          np.mean((a>=edges[2])&(a<edges[3])),np.mean((a>=edges[3])&(a<edges[4])),np.mean(a>=edges[4])])
            mod=np.array([noises[c].cdf(edges[0]-locs[c][s]),noises[c].cdf(edges[1]-locs[c][s]),noises[c].cdf(edges[2]-locs[c][s]),
                          noises[c].cdf(edges[3]-locs[c][s]),noises[c].cdf(edges[4]-locs[c][s]),1-noises[c].cdf(edges[4]-locs[c][s])])
            mod=np.diff(np.concatenate([[0],mod]))
            print(f'  {s} emp={np.round(emp,2)} mod={np.round(mod,2)}')

import numpy as np
from scipy import stats, optimize
from data import D, SEGS, CHECKS

def resid(c, locs=None):
    out={}
    for s in SEGS:
        a=np.array(D[(c,s)])
        out[s]=a-(np.median(a) if locs is None else locs[s])
    return out

def ks_1samp(x, cdf):
    x=np.sort(np.asarray(x,float)); n=len(x)
    f=cdf(x)
    return max(np.max(np.abs(f-np.arange(1,n+1)/n)), np.max(np.abs((1-np.arange(1,n+1)/n)-f)))

def fit_lap(x):
    b=np.mean(np.abs(x)); return -np.sum(stats.laplace.logpdf(x,0,b)), b

def fit_t(x):
    def nll(th):
        df,s=th
        return -np.sum(stats.t.logpdf(x,df,loc=0,scale=s))
    best=None
    for df0 in [1.5,2,2.5,3,4,6,10]:
        r=optimize.minimize(nll,[df0,60],method='Nelder-Mead',options={'maxiter':3000})
        if best is None or r.fun<best.fun: best=r
    return best.fun,best.x

def fit_norm(x):
    s=np.std(x); return -np.sum(stats.norm.logpdf(x,0,s)), s

def fit_2lap_em(x, restarts=60, seed=1):
    rng=np.random.default_rng(seed); x=np.asarray(x,float); best=None
    def ll_of(th):
        w,b1,b2=th
        if not(0<w<1) or b1<=0.5 or b2<=0.5: return -1e18
        return np.sum(np.log(np.maximum(w*stats.laplace.pdf(x,0,b1)+(1-w)*stats.laplace.pdf(x,0,b2),1e-300)))
    for t in range(restarts):
        th=np.array([rng.uniform(0.3,0.99), rng.uniform(5,120), rng.uniform(80,3000)])
        cur=ll_of(th)
        for it in range(300):
            w,b1,b2=th
            p1=w*stats.laplace.pdf(x,0,b1); p2=(1-w)*stats.laplace.pdf(x,0,b2)
            r1=p1/(p1+p2+1e-300)
            w=r1.mean()
            b1=(r1*np.abs(x)).sum()/max(r1.sum(),1e-9)
            b2=((1-r1)*np.abs(x)).sum()/max((1-r1).sum(),1e-9)
            th=np.array([w,b1,b2])
            cur=ll_of(th)
        if best is None or cur>best[0]: best=(cur,*th)
    return best

def lapc(x,b): return 0.5+0.5*np.sign(x)*(1-np.exp(-np.abs(x)/b))

for c in CHECKS:
    pr=resid(c); x=np.concatenate([pr[s] for s in SEGS])
    print('='*72); print(c,'n=',len(x))
    ll_lap,b=fit_lap(x); print(f'  Laplace      b={b:8.2f} ll={ll_lap:9.1f} KS={ks_1samp(x,lambda v:lapc(v,b)):.3f}')
    ll_n,s=fit_norm(x); print(f'  Normal       s={s:8.2f} ll={ll_n:9.1f} KS={ks_1samp(x,lambda v:stats.norm.cdf(v,0,s)):.3f}')
    llt,tth=fit_t(x); df,sc=tth
    print(f'  Student-t   df={df:8.2f} s={sc:8.2f} ll={llt:9.1f} KS={ks_1samp(x,lambda v:stats.t.cdf(v,df,0,sc)):.3f}')
    ll2,w,b1,b2=fit_2lap_em(x); print(f'  2-Laplace    w={w:.3f} b1={b1:.2f} b2={b2:.2f} ll={ll2:9.1f} KS={ks_1samp(x,lambda v:w*lapc(v,b1)+(1-w)*lapc(v,b2)):.3f}')
    # per-cell laplace scales -> test common-law
    print('  per-cell Laplace scales:')
    for s in SEGS:
        a=pr[s]; bb=np.mean(np.abs(a)); print(f'    {s}: b={bb:7.2f} nll={-np.sum(stats.laplace.logpdf(a,0,bb)):7.1f} n={len(a)}')
    # per-cell t fits
    print('  per-cell t (df,scale):')
    for s in SEGS:
        a=pr[s]
        best=None
        for df0 in [2,3,4,6,10,30]:
            f=lambda th: -np.sum(stats.t.logpdf(a,th[0],0,th[1]))
            r=optimize.minimize(f,[df0,40],method='Nelder-Mead')
            if best is None or r.fun<best.fun: best=r
        print(f'    {s}: df={best.x[0]:6.2f} scale={best.x[1]:7.2f} ll={-best.fun:7.1f}')

