class Mix:
    """mixture of symmetric components; comps=list of (weight, kind, scale); kind in {'lap','unif'}"""
    def __init__(self,comps):
        self.comps=comps
    def pdf(self,x):
        x=np.asarray(x,float); p=np.zeros_like(x)
        for w,k,b in self.comps:
            if k=='lap': p+=w*stats.laplace.pdf(x,0,b)
            elif k=='unif': p+=w*np.where(np.abs(x)<=b,1/(2*b),0.0)
            elif k=='norm': p+=w*stats.norm.pdf(x,0,b)
        return p
    def cdf(self,x):
        x=np.asarray(x,float); out=np.zeros_like(x)
        for w,k,b in self.comps:
            if k=='lap': out+=w*lapc(x,b)
            elif k=='unif': out+=w*np.clip((x+b)/(2*b),0,1)
            elif k=='norm': out+=w*stats.norm.cdf(x,0,b)
        return out
    def __repr__(self): return 'Mix'+str(self.comps)

