                    r=optimize.minimize_scalar(f,bounds=(loc[s]-45,loc[s]+45),method='bounded',options={'xatol':1e-5})
                    loc[s]=float(r.x)
                if kind=='lap2':
                    res2=np.concatenate([np.array(data[(c,s)])-loc[s] for s in SEGS])
                    ll,th=em_lapmix(res2,restarts=20,seed=11)
                    if th[1]>th[2]: th=np.array([1-th[0],th[2],th[1]])
                    mix=Mix([(th[0],'lap',th[1]),(1-th[0],'lap',th[2])])
                elif kind=='lap1':
                    res2=np.concatenate([np.array(data[(c,s)])-loc[s] for s in SEGS])
                    b=np.mean(np.abs(res2)); mix=Mix([(1.0,'lap',b)])
        locs[c]=loc
        bp=np.zeros((6,6))
        for i,s in enumerate(SEGS):
            if kind=='t':
                df,sc=th
                f=stats.t.cdf(EDGES-loc[s],df,0,sc)
            else:
                f=mix.cdf(EDGES-loc[s])
            bp[i]=np.diff(np.concatenate([[0.0],f,[1.0]]))
        BP[c]=bp
        info[c]=(kind,th,mix)
        if verbose:
            print(f'{c}: kind={kind} locs={[round(loc[s],1) for s in SEGS]} th={np.round(th,3)} BIC={scored[0][0]:.1f} (alts: '+', '.join(f"{k}:{b:.1f}" for b,k,_,_ in scored[1:])+')')
    return locs,BP,info

