def lapc(x,b): return 0.5+0.5*np.sign(x)*(1-np.exp(-np.abs(x)/b))

class Law:
    """Symmetric noise law."""
    def __init__(self,kind,params):
        self.kind=kind; self.p=params
    def pdf(self,x):
        x=np.asarray(x,float)
        if self.kind=='lap1': return stats.laplace.pdf(x,0,self.p[0])
        if self.kind=='lap2':
            w,b1,b2=self.p; return w*stats.laplace.pdf(x,0,b1)+(1-w)*stats.laplace.pdf(x,0,b2)
        if self.kind=='t': return stats.t.pdf(x,self.p[0],0,self.p[1])
        if self.kind=='lap1unif':
            w,b1,b2=self.p
            return w*stats.laplace.pdf(x,0,b1)+(1-w)*np.where(np.abs(x)<=b2,1/(2*b2),0.0)
    def cdf(self,x):
        x=np.asarray(x,float)
        if self.kind=='lap1': return lapc(x,self.p[0])
        if self.kind=='lap2':
            w,b1,b2=self.p; return w*lapc(x,b1)+(1-w)*lapc(x,b2)
        if self.kind=='t': return stats.t.cdf(x,self.p[0],0,self.p[1])
        if self.kind=='lap1unif':
            w,b1,b2=self.p; return w*lapc(x,b1)+(1-w)*np.clip((x+b2)/(2*b2),0,1)
    def nll(self,x): return -np.sum(np.log(np.maximum(self.pdf(x),1e-300)))
    def __repr__(self): return f'{self.kind}{np.round(self.p,2)}'

def em_lapmix(X,restarts=25,seed=0,bmin=20.0):
    rng=np.random.default_rng(seed); X=np.asarray(X,float); best=None
    for t in range(restarts):
        w=rng.uniform(0.5,0.99); b1=rng.uniform(20,120); b2=rng.uniform(100,4000)
        if rng.random()<0.5: w,b1,b2=1-w,b2,b1
        th=np.array([w,b1,b2])
        for it in range(300):
            w,b1,b2=th
            p1=w*stats.laplace.pdf(X,0,b1); p2=(1-w)*stats.laplace.pdf(X,0,b2)
            r1=p1/np.maximum(p1+p2,1e-300)
            w=r1.mean(); b1=max((r1*np.abs(X)).sum()/max(r1.sum(),1e-9),bmin); b2=max(((1-r1)*np.abs(X)).sum()/max((1-r1).sum(),1e-9),bmin)
            th=np.array([w,b1,b2])
        if th[1]>th[2]: th=np.array([1-th[0],th[2],th[1]])
        law=Law('lap2',th); ll=-law.nll(X)
        if np.isfinite(ll) and (best is None or ll>best[0]): best=(ll,th.copy())
    return best

def em_lap1unif(X,restarts=25,seed=0):
    rng=np.random.default_rng(seed); X=np.asarray(X,float); best=None
    for t in range(restarts):
        w=rng.uniform(0.5,0.99); b1=rng.uniform(20,120); b2=rng.uniform(200,4000)
        th=np.array([w,b1,b2])
        for it in range(300):
            w,b1,b2=th
            p1=w*stats.laplace.pdf(X,0,b1); p2=(1-w)*np.where(np.abs(X)<=b2,1/(2*b2),0.0)
            tot=p1+p2+1e-300; r1=p1/tot
            w=r1.mean(); b1=max((r1*np.abs(X)).sum()/max(r1.sum(),1e-9),3.0)
            b2=max(np.abs(X[~(r1>0.5)]) .mean() if (~(r1>0.5)).any() else 500,50)
            th=np.array([w,b1,b2])
        law=Law('lap1unif',th); ll=-law.nll(X)
        if np.isfinite(ll) and (best is None or ll>best[0]): best=(ll,th.copy())
    return best

def fit_law(kind,res):
    if kind=='lap1':
        b=np.mean(np.abs(res)); law=Law('lap1',[b]); return law
    if kind=='lap2':
        ll,th=em_lapmix(res); return Law('lap2',th)
    if kind=='lap1unif':
        ll,th=em_lap1unif(res); return Law('lap1unif',th)
    if kind=='t':
        f=lambda th: -np.sum(stats.t.logpdf(res,th[0],0,th[1]))
        best=None
        for df0 in [1.2,1.5,2,2.5,3,4,6,10,20]:
            r=optimize.minimize(f,[df0,60],method='Nelder-Mead',options={'maxiter':2000})
            if best is None or r.fun<best.fun: best=r
        return Law('t',best.x)
    raise ValueError(kind)

def ks_stat(x,cdf):
    x=np.sort(np.asarray(x,float)); n=len(x); F=cdf(x); i=np.arange(1,n+1)/n
    return max(np.max(np.abs(F-i)),np.max(np.abs(F-(i-1/n))))

def build_model(data=None, verbose=True, kinds=('lap1','lap2','lap1unif','t'), iters=3):
    data=data or D
    locs={}; BP={}; laws={}
    for c in CHECKS:
        loc={s:float(np.median(data[(c,s)])) for s in SEGS}
        law=None
        for it in range(iters):
            res=np.concatenate([np.array(data[(c,s)])-loc[s] for s in SEGS])
            cand=[]
            for k in kinds:
                L=fit_law(k,res); cand.append((k,L))
            n=len(res)
            best=min(((2*L.nll(res)+{'lap1':1,'lap2':3,'lap1unif':3,'t':2}[k]*np.log(n),k,L) for k,L in cand), key=lambda z:z[0])
            bic,kind,law=best
            if it<iters-1:
                for s in SEGS:
                    x=np.array(data[(c,s)])
                    f=lambda L: -np.sum(np.log(np.maximum(law.pdf(x-L),1e-300)))
                    r=optimize.minimize_scalar(f,bounds=(loc[s]-45,loc[s]+45),method='bounded',options={'xatol':1e-5})
                    loc[s]=float(r.x)
        locs[c]=loc; laws[c]=law
        bp=np.zeros((6,6))
        for i,s in enumerate(SEGS):
            f=law.cdf(EDGES-loc[s]); bp[i]=np.diff(np.concatenate([[0.0],f,[1.0]]))
        BP[c]=bp
        if verbose:
            res=np.concatenate([np.array(data[(c,s)])-loc[s] for s in SEGS])
            print(f'{c}: {law}  locs={[round(loc[s],1) for s in SEGS]} BIC={bic:.1f} KS={ks_stat(res,law.cdf):.3f}')
    return locs,BP,laws

